from pathlib import Path
import csv, json, zipfile, shutil

ROOT = Path(r"C:/Users/Aornob/PowerBI-Portfolio")
SOURCE = ROOT / "projects/01-warehouse-operations/data/warehouse_orders.csv"
PROJECT_HTML = ROOT / "projects/01-warehouse-operations/advanced_dashboard.html"
SITE = ROOT / "site"
SITE.mkdir(parents=True, exist_ok=True)

with SOURCE.open(encoding="utf-8-sig", newline="") as f:
    rows = list(csv.DictReader(f))
for row in rows:
    for key in ("OrderedQty", "PickedQty", "PickMinutes", "DockWaitMinutes"):
        row[key] = int(row[key])
    row["OrderValueEUR"] = float(row["OrderValueEUR"])

DATA = json.dumps(rows, ensure_ascii=False, separators=(",", ":"))
